insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('90a2ae5f-3f19-4289-983b-90a3660b1de9', 'ja', '礼儀のサインや冷たいサインを無視すると、何が起こりますか？', '["惹かれる気持ちが、ゆっくり育つ", "心地よさが下がる", "やり取りが深まる", "関心がはっきりする"]'::jsonb, 'サインを無視すると、緊張と不快感が増します。こうしたサインに気づいたら、切り上げましょう。')
