insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('92fc8147-e976-4d33-824a-5ea94444d15c', 'ja', '外れた推測でも、なぜうまくいくことが多いのですか？', '["訂正することでも、関わりと会話の流れが生まれるから", "外れることで、プレッシャーが下がるから", "女性は、男性の間違いを正すのが好きだから"]'::jsonb, '当たっていても外れていても、彼女は答えるために関わることになります。目指すのは、その関わりです。')
