insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('99e493d5-07b4-4d19-ad59-483e3579a8d1', 'ja', '意見を聞くひと言の切り出し方を、効果的にするものは何ですか？', '["適当にではなく、なぜ彼女に聞いているのかを説明している", "彼女の視点を、価値があり重要なものとして位置づけている", "議論の構図をつくり、緊張感と惹かれる気持ちを高めている"]'::jsonb, '人は、自分の視点が大切にされると、ぱっと明るくなります。大切にされることが、関わりを生みます。')
