insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b5ec6ba9-5bbb-4681-a239-50a711d681dd', 'ja', '議論や言い合いを切り口にしたひと言は、なぜこれほどうまくいくのですか？', '["性的な緊張感を高める、遊び心のある対立をつくるから", "問題の決着に彼女の意見を巻き込み、重要だと感じさせるから", "社会的証明を示すから（友人と話していたということ）"]'::jsonb, '議論や迷いごとの形にすると、彼女の意見を招くことになり、大切にされ、加わっていると感じてもらえます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b723c51c-c180-4bd0-900c-be66fdc3c190', 'ja', '礼儀と受け入れの一番大きな違いは、何ですか？', '["声のトーン", "ほほえむ頻度", "お互いがどれだけ気持ちを注いでいるか", "物理的な近さ"]'::jsonb, '受け入れには、参加と好奇心が含まれます。礼儀は、その場を波風なく保つことです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b765cb2c-14d9-49bf-b793-eeb611ababea', 'ja', '完璧な条件のときにしか声をかけないと、何が起こりますか？', '["まれにしかないので、一回一回の重みが大きく感じられる", "絶えず人と関わる場合に比べて、場数が少ないままになる", "的を絞ることで、声のかけ方の質が上がる"]'::jsonb, '完璧な条件を待つと、場数が減り、一回ごとのプレッシャーが上がります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b76c6af0-9df1-46cb-92cc-9c07b2d1404f', 'ja', '時間の制限は、なぜプレッシャーを減らすのに効果的なのですか？', '["知らない人との終わりの見えない会話に、縛られるわけではないと分かるから", "彼女の時間を尊重し、無駄にしないことを示すから", "時間が限られていれば、気まずく断られるリスクが減るから"]'::jsonb, '長くはいないと伝えることで、プレッシャーが減ります。最初に使いましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('b86940dc-da66-4fd6-a19f-bbbca988a036', 'ja', '不安が外に伝わるのを減らす体の調整は、どれですか？', '["急がず、ためらわず、安定したペースで歩く", "肩を上げたり丸めたりせず、後ろに引いて下げておく", "集中と意図を示すために、相手をじっと見つめる"]'::jsonb, '安定したペースと力の抜けた肩は、話す前に、目に見える緊張を減らします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ba3e426f-7282-4d49-a10f-46c3512816fc', 'ja', '彼女はどちらともつかない反応をし、こちらがはっきりした一歩を踏み出すと、断られます。次にどうするべきですか？', '["お礼を言って、落ち着いて立ち去る", "言い方を変えて、もう一度試す", "自分の関心を正当化する", "話題を変える"]'::jsonb, '断りは、はっきりした境界線です。落ち着いて受け入れ、取り乱さずに立ち去りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bb7584e8-d1df-4dc9-a2bf-59a289ba6852', 'ja', '方向を決める代わりに、相手に反応するだけになると、何が起こりますか？', '["先へ進む前に、やり取りにもっと時間が必要だった", "場の空気を手放すことになる。彼女が代わりに距離を縮めてくれることはない", "距離を縮める前に、タイミングが良くなる"]'::jsonb, 'リードをやめると、会話の流れは弱まります。自分から動いて、距離を縮めましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc490fe2-1fae-42f6-b95e-718da8dccc05', 'ja', '敬意のあるやり取りのために、早い段階でサインを読み取ることがなぜ欠かせないのですか？', '["彼女の最初の振る舞いが、どこまで続けていいかを示すから", "女性は、関心を示す前に、安全だと感じる必要があるから", "早い段階のサインが、彼女がまだ開いていない境界線を越えるのを防ぐから", "上のすべて"]'::jsonb, '彼女の心地よさが最優先です。続けるか、引くかを決めるために、サインを使いましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('bc5cb121-8a63-45f6-8e11-7d46e1ff9ec2', 'ja', '男性の「自分の軸」を強くする特徴は、どれですか？', '["はっきりした自己信頼", "断られても平気でいられること", "方向をリードすること", "承認を求めること"]'::jsonb, 'はっきりした自己信頼とリードする姿勢が、自分の軸を強くします。承認を求める行動は避けましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c1dd9ccd-317b-4320-a1f4-5bbb6553f846', 'ja', '声をかけます。彼女はほほえみ、こちらを向き、温かいトーンで「どうしました？」と尋ねます。', '["受け入れのサイン。心を開いている。そのままやり取りを深めていく", "礼儀のサイン。感じよくしてくれているだけ。まず、もうひと言で確かめる", "不明。関心の度合いを判断するには、もっと材料が必要"]'::jsonb, '彼女が質問や開いた姿勢で気持ちを注いでいるなら、関心はあります。流れを保ちましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c229e235-368e-47aa-9571-c1345d6402cf', 'ja', 'カフェで女性に声をかけます。「大切にされている」と感じてもらえるひと言は、どれですか？', '["「こんにちは。ここにはよく来るんですか？」", "「女性の意見を聞きたいことがあって」", "「何を飲んでいるんですか？」", "「今日、素敵ですね」"]'::jsonb, '彼女の判断をはっきり求めることで、彼女の役割が引き上げられ、関わりが生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c321230f-a277-4593-bdeb-01167899a30c', 'ja', 'スーパーで、「健康オタクっぽいですね。当たっていますか？」と言います。彼女は笑います。何がうまくいっていますか？', '["遊び心のある推測が彼女を巻き込み、すぐに軽い掛け合いが生まれた", "大胆な言い切りで、自信を示した", "なぜ健康志向だと思ったのか、好奇心を生んだ"]'::jsonb, '笑いと訂正は、関わっているという意味です。その遊び心のある空気のまま、話を広げましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c36a094c-8b8b-4c97-b801-f551071a78ed', 'ja', '彼女は、アートっぽいヴィンテージ風の服を着ています。推測をうまく使っているひと言は、どれですか？', '["「そのスタイル、すごくいいですね。いつもどこで買うんですか？」", "「クリエイティブなお仕事をしていそうですね。当たっていますか？」", "「絶対、古着屋めぐりをしていますよね？」", "クリエイティブな仕事の推測と、古着屋めぐりの推測の、どちらでも"]'::jsonb, 'どちらも、認めるか、否定するか、説明するかで、彼女が関わることを必要とします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c387493a-0ebd-41c3-b083-1a639c5a593d', 'ja', '早い段階で謝ることは、なぜ最初のひと言を弱くするのですか？', '["立ち位置を下げるから", "「邪魔をしている」と伝えるから", "主導権を彼女に渡すから", "上のすべて"]'::jsonb, '謝ると、自分を「邪魔者」として位置づけることになります。代わりに、そこにいて当然のように話しかけましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c3fe310a-e657-4693-8a1b-acee8218f2a8', 'ja', '推測から入るひと言を、当てずっぽうではなく、よく見ていると感じさせる指針は何ですか？', '["自信を持って伝える", "目に見える根拠にもとづかせる", "あいまいにしておく", "挑戦的なものにする"]'::jsonb, '目に見える手がかりにもとづいた推測は、でたらめではなく、よく考えられたものに感じられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c41c83a5-d2fe-4cdf-b37f-bcec922ef1d8', 'ja', '「友人にはおかしいと言われるんですが、…する人って、…だと思うんですよね」。このひと言は、何をしていますか？', '["彼女の意見が決着の鍵になる、議論の構図をつくる", "惹かれる気持ちを築くために、人柄とユーモアのセンスを見せる", "言い寄られていると感じさせ、彼女を警戒させる"]'::jsonb, '議論や迷いごとの形にすると、彼女の意見を招くことになり、大切にされ、加わっていると感じてもらえます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4e94987-68b3-4c33-b481-27950bb88e63', 'ja', '意図を伝えるストレートなひと言に最も合う環境は、どれですか？', '["スーパー", "静かな図書館", "病院の待合室", "夜の社交の場"]'::jsonb, 'ストレートな意図は、バーやナイトクラブのように、出会いのためにつくられた環境に合います。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c4ec10a6-7307-4d33-b4ac-bab091417d95', 'ja', '最初のひと言で謝ることは、なぜ空気をリードする力を弱めるのですか？', '["彼女のしていることのほうが大事だ、という前提に立つから", "リードする代わりに、許可を求めるから", "自分の存在を「邪魔」として位置づけるから", "その場を自信を持って引き受けていることを示すから"]'::jsonb, '謝罪は、自分を「選択肢」ではなく「邪魔者」として位置づけます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c728f4f6-0836-4faf-b386-b10c475ae132', 'ja', 'さりげないひと言は、なぜストレートなひと言よりもプレッシャーが少ないのですか？', '["恋愛的な関心を、すぐに宣言するから", "声をかけたことを、何気ない共有の場面のように見せるから", "やり取りが自然に育つ余地を残すから", "その場の状況についてのひと言の陰に、意図を隠すから"]'::jsonb, '同じ状況を共有していると、話しかけられることが自然に感じられ、応じやすくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('c9f1e798-7318-4c31-b9db-3d51fbde0554', 'ja', '推測から入るひと言が相手を引き込む、一番の理由は何ですか？', '["質問よりも、自信があるように感じられるから", "恋愛的な意図を、早い段階で伝えるから", "何も考えずに答えるのではなく、自分から反応することを彼女に求めるから"]'::jsonb, '推測は、反応を求めます。彼女は、訂正するか認めるかで、すぐに会話に加わることになります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cad92129-8727-4718-bff9-4ab66c366d32', 'ja', '意見を聞くひと言は、なぜ最初から相手を強く引き込むのですか？', '["自分の視点が重要だと、彼女に感じさせるから", "彼女を、その判断に価値のある人として位置づけるから", "取引のようで、すぐに受け流されるから", "彼女の意見を大切にすることで、助けになるから"]'::jsonb, '人は、話を聞いてもらえ、真剣に受け止めてもらえていると感じたときに、応えてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cb1b3910-7f46-4638-b7ba-949483f7d10a', 'ja', 'バーで、彼女と一緒に静かな場所へ移動しました。次はどうしますか？', '["会話を続け、別の日に会おうと提案する", "流れが良いうちに、今、連絡先を聞く", "一緒に別の場所へ移ろうと提案する", "状況と彼女のサインに応じて、LINEを聞くか、一緒に別の場所へ移ろうと提案する"]'::jsonb, '流れが良いときは、次の一歩に進みましょう。連絡先を交換するか、彼女のサインが「はい」と言っているなら、別の場所で続けようと提案します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ccb554b7-2aa7-47d7-a64b-d4d9612a37a1', 'ja', '近づく角度や距離によって、なぜ不快感が生まれることがあるのですか？', '["脅威への自動的な反応を引き起こすから", "動ける余地や出口をふさぐから", "近づいているあいだ、意図が見えなくなるから", "いつでも、高い自信を示すから"]'::jsonb, '角度や距離が悪いと、踏み込まれたように感じられます。それは、意識して選ぶより先に起こります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cd75e2e6-d17a-4bb7-93e9-0f592f46fef8', 'ja', '自分がつくる場の空気は、なぜ彼女がそれまでしていたことよりも面白くなければならないのですか？', '["そうでなければ、彼女は元のことに戻るから", "人間は、面白いものに注意を向けるようにできているから", "ほかの気を引くものに負けないよう、彼女の注意をつかむ必要があるから", "上のすべて"]'::jsonb, 'どれも正しいです。こちらのつくる空気が、彼女の今の現実より魅力的でなければ、彼女は元のことに戻ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ceadc18e-3007-4ed0-beba-55eb062fbd75', 'ja', '会話はうまくいっています。彼女が出身を尋ねてきます。答えたあと、どうしますか？', '["リードを保つために、別の質問を彼女にする", "話し続けるために、自分の答えをくわしく広げる", "聞いていることを示すために、次の質問は彼女に任せる"]'::jsonb, '空気をリードするとは、会話を前へ導くことです。答えてから、方向を変えましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('cf063d07-0835-4825-9d56-79f6e3255038', 'ja', '魅力的だと思ったと伝えます。彼女はお礼を言いますが、返事は短いままです。', '["自信を示すために、さらに押す", "緊張をやわらげるために、雑談に切り替える", "礼儀正しく締めくくり、彼女が心地よいまま立ち去る"]'::jsonb, 'はっきり意図を伝えたあとの最小限の返事は、関心がお互いのものではないという意味です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d0ec47ae-1140-4d62-b956-39af81780946', 'ja', '空気をしっかりリードできていることを示す行動は、どれですか？', '["落ち着いた確信", "優柔不断", "話題の切り替えをリードすること", "同意を必要とすること"]'::jsonb, '場の空気は、同意ではなく、方向づけによって保たれます。確認するのではなく、導きましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d1f7d186-8772-4b75-bb24-e34679605860', 'ja', '二人とも犬の散歩中で、犬同士が遊び始めます。さりげないひと言としてうまくいくのは、どれですか？', '["犬同士の仲の良さについてひと言言う", "彼女か、彼女の犬の見た目を褒める", "彼女の犬の犬種を聞く", "この公園にはよく来るのかを聞く"]'::jsonb, '共有している体験から離れずにいると、安心感が自然に育っていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d3daff27-e652-43a8-8f20-af94b5be0f32', 'ja', '路上で、彼女は感じがいいのですが、関心があるのかどうか分かりません。次の一手として一番良いのは何ですか？', '["彼女の隣を歩きながら、話し続ける", "エネルギーを下げて、彼女のペースに合わせる", "「感じのいい方ですね。今度、コーヒーでもどうですか？」と言う"]'::jsonb, 'シンプルな誘いは、続きを無理強いすることなく、乗るか断るかをはっきり選べるようにします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d43846a5-78ac-402f-95a0-7cfcb54078ce', 'ja', 'どちらともつかない反応のあと、だらだら続けるのではなく、はっきりさせることがなぜ役立つのですか？', '["彼女に、「はい」か「いいえ」かのはっきりした選択肢を渡すから", "気まずく長引くのを短くするから", "惹かれているかどうかを、無理に明かさせるから", "推測する必要がなくなるから"]'::jsonb, 'はっきりしたひと言は、その礼儀正しさが関心なのか、ただの礼儀なのかを明らかにして、あいまいさを取り除きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d466b22a-5014-4620-9cfa-19217d091ad6', 'ja', '効果的なさりげないひと言は、どれですか？', '["周りの環境についてひと言言うこと", "二人が置かれている状況について尋ねること", "共有している体験に気づくこと", "見た目を褒めること"]'::jsonb, '同じ状況を共有していると、話しかけられることが自然に感じられ、応じやすくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d61d2413-5ee2-43c8-8cce-8d6030c1879e', 'ja', '最初のひと言で、空気をリードする力を失わせるものは何ですか？', '["許可を求める代わりに、言い切りで話しかけること", "声をかけたことや、さえぎったことを謝ること", "まず、話しかけてもいいかどうかを尋ねること"]'::jsonb, '謝ると、自分を「邪魔者」として位置づけることになります。代わりに、そこにいて当然のように話しかけましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d743d469-5774-4931-80b8-cf68fa8054d1', 'ja', '30秒ためらっているうちに、ほかの誰かが先に彼女に声をかけます。原因は何ですか？', '["やめておく理由を考える時間を、脳に与えたこと", "良い最初のひと言がなかったこと", "彼女にはっきり関心がなかったこと", "準備が十分だと感じられなかったこと"]'::jsonb, 'すばやく動けば、迷いがふくらむのを止められます。彼女に気づいてから3秒以内に動きましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('d76f2c05-59de-4480-a3a4-8dbe27fb2854', 'ja', '3秒ルールは、なぜうまくいくのですか？', '["完璧な最初のひと言を準備する時間ができるから", "まず、彼女の関心の度合いを見きわめられるから", "脅威を察知する働きが抵抗を強める前に、動けるから"]'::jsonb, 'このルールが効くのは、脳が「やめておく理由」をつくり出す前に動くからです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('daf41a36-31b3-4cc7-b731-be0601f73a66', 'ja', '好奇心を引くひと言は、なぜより効果的に注意をつかむのですか？', '["警戒を下げるから", "義務感を生むから", "判断を先延ばしにするから", "興味を引き起こすから"]'::jsonb, '好奇心が効くのは、自然に注意を引きつけるからです。興味をそそるひと言で始めましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc0ff18e-1928-43e2-b403-e3cb7a6b3ab2', 'ja', '会話が退屈な話題に流れます。空気をリードするとは、どうすることですか？', '["聞いていて関心があることを示すために、彼女の流れについていく", "彼女の話題を退けることなく、自分がもっと面白いと思う話題へ向け直す", "ほかのことを話したいと、彼女に伝える"]'::jsonb, 'その場の話を受け止めたうえで、もっとエネルギーの高い話題へと舵を切りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('dc4c48ee-7f80-40c8-8355-cfd7dfdf8159', 'ja', 'カフェで声をかけます。彼女は温かくほほえみますが、返事は短く、体をそむけます。', '["受け入れのサイン。返事は短くても、温かい笑顔は関心を示している", "礼儀のサイン。感じよくするためにほほえんでいるが、ボディランゲージはためらいを示している", "不明。入り混じったサインなので、見きわめるにはもっとやり取りが必要"]'::jsonb, '返事が短く、体がそむけられているときは、その境界線を尊重して、切り上げましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ddf26019-643c-48e3-99bd-8ed12168ae51', 'ja', '電車の中で、自分の大好きな本を読んでいる女性を見かけます。失敗が確定するのは、どれですか？', '["声をかけて、断られること", "ためらって、まったく声をかけないこと", "彼女が先に話しかけてくるのを待つこと", "ほほえむだけで、何も言わないこと"]'::jsonb, '動かなければ、可能性はゼロで確定します。動けば、起こりうる結果が生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('df7b348f-77a6-43b4-b9c2-72ba495cd148', 'ja', '彼女はほほえみ、答え、質問を返してきます。一番良い動きはどれですか？', '["すばやく距離を縮める", "やり取りのペースを落とす", "彼女を褒める", "自然に続ける"]'::jsonb, '彼女が同じだけ返してくれるなら、ペースを無理に上げず、自然に続けて流れをつくりましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0a819cd-0a51-464f-ae01-bb50bf45ca1b', 'ja', '「こんにちは」と声をかけます。彼女は名前を名乗り、目を合わせたまま、出身を尋ねてきます。', '["受け入れていて、このやり取りに気持ちを注いでいる", "礼儀正しく、人付き合いの決まりに従っている", "あとで決めるために、情報を集めている"]'::jsonb, '名前を名乗り返すことと、続けて質問してくることは、受け身の礼儀ではなく、積極的な関心を示しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e0b6a830-3f63-4d2b-b958-5db45a154beb', 'ja', '礼儀を受け入れと取り違えることは、なぜよくある間違いなのですか？', '["男性は関心を見たいので、礼儀正しい振る舞いを深読みするから", "女性は礼儀正しくするよう教えられていて、男性がそれを「惹かれている」と取り違えるから", "礼儀のサインには笑顔や温かさが含まれ、男性はそれを関心と読むから", "上のすべて"]'::jsonb, '礼儀のサインは、あえてやわらかくしてあります。代わりに、注意が続いているかどうかと、質問が返ってくるかどうかを頼りにしましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e1d6b84b-cc78-420d-8d46-30d10f8f2b0a', 'ja', '彼女は温かく関わり、腕に触れ、質問もしてきますが、そのあと「呼んだタクシーが来ました」と言います。', '["時間の限られた受け入れのサイン。タクシーに乗る前に、連絡先を交換する", "礼儀のサイン。触れたのも質問も、予定どおり帰る前の礼儀だった", "入り混じったサイン。彼女は時間の制約を口にした"]'::jsonb, 'しっかり関わってくれていて、本当に時間の制約があるなら、それはすぐにLINEを交換する合図です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2a6f6e8-963f-4da4-bfc3-a9cc1b615ab4', 'ja', '受け入れている関心を示す行動のサインは、どれですか？', '["返事は短いが、安定して目を合わせている", "答えるときに、体をまっすぐこちらに向ける", "質問を返したり、自分から会話に加わったりする"]'::jsonb, '彼女が質問や開いた姿勢で気持ちを注いでいるなら、関心はあります。流れを保ちましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e2e4a209-5fc0-4faf-a13c-67ed31a8a170', 'ja', '準備ができている、計画した外出のときにしか声をかけません。これは何を制限しますか？', '["練習の総量と場数", "完璧なやり取りができる可能性", "見た目の基準"]'::jsonb, '場面を選んで取り組むと、場数が少ないままになり、スキルの上達が遅くなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e3b36edc-fa81-4ae9-ba6b-80b396e930c4', 'ja', '外れた推測が、それでも効果的なのはなぜですか？', '["彼女が訂正するかもしれず、それも関わりだから", "訂正が、本当のことを説明する流れにつながることが多いから", "外れることで弱さが見え、それが信頼を築くから"]'::jsonb, '外れた推測は、訂正と説明を通じて、関わりを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e549d946-f5c9-48d5-8ed3-03653b7ab3b6', 'ja', '二人とも、静かな書店で本を見ています。プレッシャーを減らす最初のひと言は、どれですか？', '["「本が好きそうですね」", "「本を持っている姿、似合いますね」", "「連絡先を教えてもらえますか？」", "「最近、ここで何かいい本に出会いましたか？」"]'::jsonb, 'その場で共有している体験が、会話を自然に始めさせてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e5eae06f-7a14-4c9f-ab68-d799aa9f603d', 'ja', '彼女は好意的に応じてくれますが、「もうすぐ友達のところに戻らないと」と言います。どう動きますか？', '["受け入れの反応なので、時間の制約を口にされても続ける", "限られた時間で強い印象を残してから、彼女を行かせる", "尊重する。受け止めたうえで、すっきり切り上げるか、手短に連絡先を交換する"]'::jsonb, '受け入れられていても、時間の制限がなくなるわけではありません。流れは短く保つか、手早く次へ移りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('e6f7a034-55b9-4303-a1f2-e70269b09f81', 'ja', 'アートのようなタトゥーを入れた女性を見かけます。相手を引き込むひと言は、どれですか？', '["「こんばんは。今夜の調子はどうですか？」", "「クリエイティブな分野で働いていそうな方ですね」", "「お仕事は何をしているんですか？」", "「素敵ですね」"]'::jsonb, '具体的な推測は、彼女が自分のこととして関わり、答えることを求めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ea6aac0e-0b64-4be8-aa43-1990315262e0', 'ja', '「きれいな方だなと思って、どうしても声をかけたくて」と言います。彼女は顔を赤らめてお礼を言いますが、返事は短いです。', '["関心が続いていることを示すために、もう一度褒める", "安心してもらうために、内気なところをからかう", "感じよく立ち去る。ストレートなひと言のあとに返ってくるものが少ないのは、関心がないサイン"]'::jsonb, '顔を赤らめるのは、礼儀の場合もあります。ストレートなひと言のあとの短い返事は、関心がないという意味です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ed852bcc-77f4-436a-9582-103cc2537be6', 'ja', '「お見かけして、ひと言ごあいさつしたくて」と言います。彼女は笑って「こんにちは」と返し、仕事は何をしているのかと尋ねてきます。', '["社交の場なので、礼儀正しくしているだけ", "同じだけ返していて、続けることに前向き", "驚いていて、見きわめるための時間を稼いでいる"]'::jsonb, '笑いと質問のお返しは、同じだけ返していることと、続けたいという本物の関心を示しています。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f0dd9eca-d510-4237-8ce4-290954082900', 'ja', '場の空気を、彼女が今していることよりも面白くする要素は、どれですか？', '["彼女をすぐに巻き込む、遊び心のある推測をすること", "彼女が興味を持てることについて、意見を求めること", "周りの環境よりも、声を大きく、エネルギーを高くすること"]'::jsonb, '関わりは、声の大きさからではなく、巻き込むことから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f17c4317-4ac6-4db1-838b-c39a93c3de0f', 'ja', 'バーで、彼女は感じがいいのですが、関心があるのかどうか分かりません。次の一手として一番良いのは何ですか？', '["「一緒に飲み物を取りに行きませんか？」と尋ねる", "大胆なスキンシップで距離を縮める", "つながりを築くために、もっと踏み込んだ質問をする", "彼女がまた関わってくるか、黙って待つ"]'::jsonb, 'シンプルな誘いは、続きを無理強いすることなく、乗るか断るかをはっきり選べるようにします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2b0e5af-f8e1-480b-aa9a-969dfa406d42', 'ja', '彼女はこちらを向き、温かくほほえみ、ていねいに答え、話しながら髪を直します。', '["強い受け入れのサイン。体の向き、笑顔、ていねいな答え、髪に触れるしぐさのすべてが関心を示している", "礼儀のサイン。感じよくしているだけで、髪に触れたのは偶然", "緊張。このやり取りに不安を感じているだけで、関心があるとは限らない"]'::jsonb, '好意的な手がかりがいくつも重なっているのは、受け入れのサインです。そのまま続けましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('f2ebba26-20ab-4f42-bd4e-eda08aa656ef', 'ja', '謝罪から話しかけることは、なぜやり取りを弱くするのですか？', '["タイミングが悪いから", "惹かれる気持ちが弱いから", "自分を「邪魔者」として位置づけるから", "彼女に恋人がいたから"]'::jsonb, '謝ると、自分を「邪魔者」として位置づけることになります。代わりに、そこにいて当然のように話しかけましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fb2737de-57ac-46ae-bfd8-662497358e2a', 'ja', '場の空気をつくるうえで、ミステリアスさはなぜ効果的なのですか？', '["次に何を言うのか彼女には分からず、好奇心と注意が生まれるから", "すぐに分類されて、片づけられてしまうのを防ぐから", "女性は、ミステリアスな男性に自然と惹かれるから"]'::jsonb, 'ミステリアスさは、次に何が来るのかという好奇心を高め、注意をつかみます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbb58fb-2105-465e-9bb2-95117c0d4ee4', 'ja', '彼女は体をまっすぐこちらに向けてほほえみますが、「今夜は、あまり人と話す気分じゃなくて」と言います。', '["礼儀正しいお断り。ボディランゲージは好意的でも、言葉は関心がないことを示している", "テスト。断りを押してでも粘るかどうかを見ている", "入り混じったサイン。体は「はい」、言葉は「いいえ」と言っている。やさしく押し切る"]'::jsonb, '礼儀正しいボディランゲージが、口にされた境界線を上書きすることはありません。受け止めて、立ち去りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('fdbdc05b-610e-4954-bace-34af89e1f619', 'ja', 'ストレートなひと言のあと、彼女は短く笑いますが、すぐに店内を見回します。', '["注意を取り戻すために、エネルギーを上げる", "流れが弱まる前に、LINEを聞く", "やり取りを自然に終わらせる"]'::jsonb, '笑いは、礼儀の場合もあります。注意が分散しているなら、引くときです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('ff750d3c-1bf6-4368-bb6c-04dc1b70a29b', 'ja', '時間の制限は、心理的になぜ効くのですか？', '["その場面が長い付き合いに感じられないと、脳がリラックスするから", "終わりの見えない会話に縛られるわけではないと分かって、彼女の警戒が下がるから", "希少性が生まれ、こちらがより価値のある存在に見えるから"]'::jsonb, '制限があると、「抜け出せなくなる」という不安がなくなり、安心感が増します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
